(3264326, 454038, 17203, '<td valign="top">Not very appealing, but WOW! 10</td>', 'Not very appealing, but WOW! 10', '2007-01-22 00:06:51.000000', NULL, 1),
(3264335, 455810, 15711, '<td valign="top">GREAT capture.  WOW - love the diagonal line of his spread wings against the arch of the background.  Nice off centering.</td>', 'GREAT capture.  WOW - love the diagonal line of his spread wings against the arch of the background.  Nice off centering.', '2007-01-22 00:08:29.000000', NULL, 1),
(3264336, 456355, 37252, '<td valign="top">Sharpness is good - too bad the shadows are so dark. I would have liked to see more of the spines on his back.</td>', 'Sharpness is good - too bad the shadows are so dark. I would have liked to see more of the spines on his back.', '2007-01-22 00:08:29.000000', NULL, 1),
(3264340, 456410, 15711, '<td valign="top">HA HA HA HA What a split second shutter snap. What an odd olive background color.  I like it.</td>', 'HA HA HA HA What a split second shutter snap. What an odd olive background color.  I like it.', '2007-01-22 00:09:33.000000', NULL, 1),
