(3267464, 455226, 32345, '<td valign="top">Not 100% sure, but this looks a lot like the Biôdome in Montréal. It''s a very nice picture. Well done. <br/> <br/>PS I don''t score lower for Zoo pictures.</td>', 'Not 100% sure, but this looks a lot like the Biôdome in Montréal. It''s a very nice picture. Well done.  PS I don''t score lower for Zoo pictures.', '2007-01-22 16:20:35.000000', NULL, 1),
(3267466, 456519, 54475, '<td valign="top">Very beautiful good color I love this one 10</td>', 'Very beautiful good color I love this one 10', '2007-01-22 16:21:08.000000', NULL, 1),
(3267467, 455826, 45631, '<td valign="top">Like the composition of this shot and the tones all work together for me. 8</td>', 'Like the composition of this shot and the tones all work together for me. 8', '2007-01-22 16:21:09.000000', NULL, 1),
(3267469, 455941, 45631, '<td valign="top">Great shot and very cute. 9</td>', 'Great shot and very cute. 9', '2007-01-22 16:21:50.000000', NULL, 1),
