INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3272007, 454073, 65234, '<td valign="top">Wonder how many people get your reference?  Anyway, nice shot.  Johnathan Seagull (or his cousin) stands out beautifully against the sky.</td>', 'Wonder how many people get your reference?  Anyway, nice shot.  Johnathan Seagull (or his cousin) stands out beautifully against the sky.', '2007-01-23 18:18:53.000000', NULL, 1),
(3272009, 456359, 65234, '<td valign="top">Nice timing!</td>', 'Nice timing!', '2007-01-23 18:20:17.000000', NULL, 1),
(3272014, 455746, 65234, '<td valign="top">Even the wild ones need to rest and recuperate now and again ;-)  I like the shine in the neck feathers and the tracks of all his friends around him.</td>', 'Even the wild ones need to rest and recuperate now and again ;-)  I like the shine in the neck feathers and the tracks of all his friends around him.', '2007-01-23 18:21:47.000000', NULL, 1),
