INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3276384, 454620, 56502, '<td valign="top">What a fitting caption!</td>', 'What a fitting caption!', '2007-01-24 15:54:13.000000', NULL, 1),
(3276388, 455833, 41337, '<td valign="top">I envy your lens reach. Good capture.</td>', 'I envy your lens reach. Good capture.', '2007-01-24 15:56:53.000000', NULL, 1),
(3276394, 455268, 41337, '<td valign="top">He has a strong presence and you made sure to preserved that in your capture.</td>', 'He has a strong presence and you made sure to preserved that in your capture.', '2007-01-24 15:59:31.000000', NULL, 1),
(3276412, 456512, 56502, '<td valign="top">Maybe it was just not enough light around at the time of the day, still I''d prefer a bit more contrast.</td>', 'Maybe it was just not enough light around at the time of the day, still I''d prefer a bit more contrast.', '2007-01-24 16:03:34.000000', NULL, 1),
(3276420, 455972, 56502, '<td valign="top">Nice picture, but the sharpening created very visible halos around the twigs.</td>', 'Nice picture, but the sharpening created very visible halos around the twigs.', '2007-01-24 16:05:56.000000', NULL, 1),
(3276424, 456222, 41337, '<td valign="top">In an odd way this reminds me of my entry "From the Ground Up III" challenge. The beak close to the frame like that heightens it''s dagger like quality. So in other words the composition works for me. The lighting while sufficient could have used some more fill light, which if impossible in-camera could have been accomplished in post. Just my opinion.</td>', 'In an odd way this reminds me of my entry "From the Ground Up III" challenge. The beak close to the frame like that heightens it''s dagger like quality. So in other words the composition works for me. The lighting while sufficient could have used some more fill light, which if impossible in-camera could have been accomplished in post. Just my opinion.', '2007-01-24 16:06:12.000000', NULL, 1),
(3276447, 456512, 41337, '<td valign="top">Very interesting.</td>', 'Very interesting.', '2007-01-24 16:11:54.000000', NULL, 1),
(3276455, 456125, 41337, '<td valign="top">I''d be interested to know if this was very saturated or not but regardless the look of it is pleasing as is the position of it''s wings.</td>', 'I''d be interested to know if this was very saturated or not but regardless the look of it is pleasing as is the position of it''s wings.', '2007-01-24 16:14:06.000000', NULL, 1),
(3276462, 456655, 41337, '<td valign="top">Nicely composed with good detail.</td>', 'Nicely composed with good detail.', '2007-01-24 16:15:02.000000', NULL, 1),
(3276467, 456283, 56502, '<td valign="top">The rough background doesn''t seem so ideal for the birds in the size they have on the picture, they are not so good to discern from the background.</td>', 'The rough background doesn''t seem so ideal for the birds in the size they have on the picture, they are not so good to discern from the background.', '2007-01-24 16:16:01.000000', NULL, 1),
(3276471, 455830, 41337, '<td valign="top">I like this. There''s a real feeling of gravity starting to pull down on the bird as it just starts to flap it''s wings. Excellent capture.</td>', 'I like this. There''s a real feeling of gravity starting to pull down on the bird as it just starts to flap it''s wings. Excellent capture.', '2007-01-24 16:16:51.000000', NULL, 1),
(3276497, 455817, 41337, '<td valign="top">The composition works well. I am curious to see it cropped for comparision so that there is an equilibrium reached between the lights and the darks which I think would also make for an interesting composition.</td>', 'The composition works well. I am curious to see it cropped for comparision so that there is an equilibrium reached between the lights and the darks which I think would also make for an interesting composition.', '2007-01-24 16:21:28.000000', NULL, 1),
(3276499, 455995, 41337, '<td valign="top">Geez. You''ve captured each one of these birds with a human characteristic that I wish I could achieve.</td>', 'Geez. You''ve captured each one of these birds with a human characteristic that I wish I could achieve.', '2007-01-24 16:22:57.000000', NULL, 1),
