(3276515, 456422, 41337, '<td valign="top">Nicely captured. I only wish I saw more of it''s environment.</td>', 'Nicely captured. I only wish I saw more of it''s environment.', '2007-01-24 16:26:56.000000', NULL, 1),
(3276517, 456770, 41337, '<td valign="top">That''s some detail you managed to achieved.</td>', 'That''s some detail you managed to achieved.', '2007-01-24 16:28:02.000000', NULL, 1),
