(3285733, 455244, 6132, '<td valign="top">A cute image</td>', 'A cute image', '2007-01-26 08:28:42.000000', NULL, 1),
(3285739, 456769, 67258, '<td valign="top">Fabulous pose, and quite intimidating!  I am glad you didn''t crop in too tight, and left plenty of the background to give context to the shot.  I could imagine seeing this as an illustration in a wildlife book - good work!</td>', 'Fabulous pose, and quite intimidating!  I am glad you didn''t crop in too tight, and left plenty of the background to give context to the shot.  I could imagine seeing this as an illustration in a wildlife book - good work!', '2007-01-26 08:29:38.000000', NULL, 1),
(3285741, 456311, 6132, '<td valign="top">Beautiful colours that you have captured, really like the composition.</td>', 'Beautiful colours that you have captured, really like the composition.', '2007-01-26 08:29:54.000000', NULL, 1),
(3285760, 456129, 67258, '<td valign="top">Such pathos!  An absolutely super photo - the detail in the fur couldn''t be bettered, and the monkey stands out perfectly from the green background.</td>', 'Such pathos!  An absolutely super photo - the detail in the fur couldn''t be bettered, and the monkey stands out perfectly from the green background.', '2007-01-26 08:37:22.000000', NULL, 1),
